-- ══════ Каталог документов РГС: это страница со ссылками, правил не содержит ══════
-- Ссылка на PDF правил №152 из него уже сохранена как источник самих правил.
delete from program_document where storage_path like 'programs/html_b7685c62%';

select 'правил Ренессанс: ' || (select count(*) from coverage_rule cr join program_document pd on pd.id=cr.document_id
  where pd.storage_path='programs/renins_dms.pdf' and pd.superseded_by_id is null);
select 'активных документов: ' || count(*) from program_document where superseded_by_id is null;
select 'всего правил: ' || count(*) from coverage_rule;
commit;
